before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <stdexcept>
int checkedReward(int score) {
    if (score < 0) throw std::invalid_argument("negative score");
    return score;
}
int main() {
    try {
        int reward = checkedReward(3);
        std::cout << "reward " << reward << "\n";
    } catch (const std::invalid_argument& error) {
        std::cout << "rejected: " << error.what() << "\n";
    }
    std::cout << "after boundary\n";
}
```

